 async function refresh(mode=view){const res=await fetch('/api/data'+(mode==='client'?'?view=client':''),{cache:'no-store'});const json:any=await res.json();if(!res.ok)throw Error(json.error);setItems(json.items);setUser(json.user);if(!json.user.admin){setView('client');if(!user)setNav('Início');}return json;}
 useEffect(()=>{refresh().catch(e=>setError(e.message)).finally(()=>setLoading(false));},[]);
 async function request(method:string,body:any){const res=await fetch('/api/data',{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const json:any=await res.json();if(!res.ok)throw Error(json.error);return json;}
 async function run(fn:()=>Promise<any>,success='Salvo.'){if(busy)return;setBusy(true);try{await fn();await refresh();tell(success);}catch(e:any){tell(e.message);}finally{setBusy(false)}}
