 function navigate(n:string){setLeadTarget(null);setLeadAction(null);setActionTarget(null);setUploadAction('');setFeedback('');setNav(n);setProject(null);setDelivery(null);setQuery('');setMobile(false)}
 function openProject(id:string){setLeadTarget(null);setLeadAction(null);setFeedback('');setActionTarget(null);setUploadAction('');setProject(id);setNav(isClient?'Meus projetos':'Projetos');setTab(isClient?'Visão geral':'Resumo');setDelivery(null);setMobile(false)}
 async function switchView(v:'admin'|'client'){setAgendaType('Todos');setAgendaProject('');setLoading(true);try{await refresh(v);setView(v);setNav(v==='client'?'Início':'Visão geral');setProject(null);setTab(v==='client'?'Visão geral':'Resumo');setDelivery(null);}catch(e:any){tell(e.message)}finally{setLoading(false)}}
 const newClient=()=>setModal({title:'Novo cliente',kind:'client',fields:[{key:'name',label:'Nome do contato',required:true},{key:'company',label:'Empresa'},{key:'email',label:'E-mail',type:'email'},{key:'notes',label:'Notas internas',type:'textarea'}]});
 const leadFields:Field[]=[{key:'name',label:'Nome do contato',required:true},{key:'company',label:'Empresa'},{key:'email',label:'E-mail',type:'email'},{key:'source',label:'Origem'},{key:'stage',label:'Etapa comercial',type:'select',options:pipeline.filter(x=>x!=='Ganho').map(value=>({value,label:pipelineLabel(value)})),value:'Novo lead'},{key:'value',label:'Valor estimado (R$)',type:'money'},{key:'next',label:'Próxima ação'},{key:'due',label:'Prazo da próxima ação',type:'date'}];
 const recommendationField:Field={key:'recommendedPath',label:'Caminho recomendado',type:'select',options:opts(recommendedPaths)};
 const qualificationQuestions:Field[]=[{key:'communicationProblem',label:'O problema principal é de comunicação?'},{key:'investigationNeeded',label:'O problema ainda precisa ser investigado?'},{key:'implementWithUs',label:'Há intenção clara de implementar conosco?'},{key:'implementationPredictable',label:'Há previsibilidade do tipo de implementação?'},{key:'operationalCapacity',label:'A execução cabe na nossa capacidade operacional?'},{key:'strategyValidated',label:'A base estratégica já está validada?'},{key:'runningCommunication',label:'A comunicação e os ativos já estão funcionando?'},{key:'needsRecurring',label:'A necessidade é evolução e acompanhamento recorrentes?'}].map(f=>({...f,type:'select',options:opts(['Sim','Não'])}));
 const macroScopes=(key:string):Field[]=>[{key:'strategicScope',label:'Strategic Phase · Audit + Strategic Direction',type:'textarea',required:true,showWhen:{key,value:'Communication Project'},hint:'Defina a investigação e a direção estratégica incluídas na contratação.'},{key:'implementationScope',label:'Implementation Phase · ativos acordados',type:'textarea',required:true,showWhen:{key,value:'Communication Project'},hint:'Defina a execução acordada. O projeto é personalizado; os ativos não são um pacote fixo.'}];
 const phaseFields:Record<string,Field[]>={Contato:leadFields.filter(f=>f.key!=='stage'),Discovery:[{key:'callDate',label:'Data da Discovery Call',type:'datetime-local'},{key:'callDone',label:'Discovery realizada',type:'checkbox'},recommendationField,{key:'notes',label:'Necessidades, contexto e decisões da Discovery',type:'textarea'},{key:'next',label:'Próxima ação'},{key:'due',label:'Prazo da próxima ação',type:'date'}],Qualificação:[...qualificationQuestions,{...recommendationField,required:true},{key:'qualificationNotes',label:'Justificativa e limites operacionais',type:'textarea'},{key:'qualificationDone',label:'Qualificação / Escopo concluído',type:'checkbox'}],Proposta:[{key:'proposalUrl',label:'Link da proposta',type:'url'},{key:'sowUrl',label:'Link do SOW',type:'url'},{key:'value',label:'Valor contratado (R$)',type:'money',required:true},{key:'projectName',label:'Nome do projeto'},{key:'service',label:'Modalidade de contratação',required:true,type:'select',options:opts(services),value:services.includes(find(leadTarget||'')?.data.recommendedPath)?find(leadTarget||'')?.data.recommendedPath:''},{key:'integration',label:'Nível de integração',required:true,type:'select',options:integrationLevels.map(value=>({value,label:integrationLabel(value)})),value:integrationFor(find(leadTarget||'')?.data.service||find(leadTarget||'')?.data.recommendedPath)},{key:'clientContact',label:'Responsável do cliente',value:find(leadTarget||'')?.data.name||''},{key:'objective',label:'Objetivo do trabalho',type:'textarea',required:true},{key:'scope',label:'Escopo contratado',type:'textarea',required:true},...macroScopes('service'),{key:'projectDue',label:'Conclusão prevista',type:'date',required:true},{key:'proposalAccepted',label:'Proposta / escopo aceitos pelo cliente',type:'checkbox'}],Negociação:[{key:'requiresContract',label:'Exigir contrato assinado para fechar',type:'checkbox',value:true},{key:'contractUrl',label:'Link do contrato',type:'url'},{key:'signed',label:'Contrato assinado e conferido',type:'checkbox'},{key:'requiresEntry',label:'Exigir entrada para fechar',type:'checkbox',value:true},{key:'entryAmount',label:'Valor da entrada (R$)',type:'money'},{key:'entryDue',label:'Vencimento da entrada',type:'date'},{key:'entry',label:'Entrada recebida e conferida',type:'checkbox'},{key:'entryDate',label:'Data do recebimento da entrada',type:'date'},{key:'balanceDue',label:'Vencimento do saldo contratado',type:'date'},{key:'paymentNote',label:'Instruções / referência do pagamento',type:'textarea'}]};
 function openLead(r:Item){const stage=pipelineStage(r.data.stage);setLeadTarget(r.id);setLeadPhase(stage==='Ganho'?'Projeto':stage==='Negociação'?'Negociação':stage==='Qualificação / Escopo'?'Qualificação':stage==='Proposta enviada'?'Proposta':stage.startsWith('Discovery')?'Discovery':'Contato');setLeadAction(null)}
 function editLeadPhase(r:Item,phase:string){setLeadPhase(phase);setModal({title:phase+' · '+(r.data.company||r.data.name),kind:'lead',item:r,fields:phaseFields[phase]||phaseFields.Contato})}
 async function commercialRequest(action:'close'|'convert',lead:Item,client?:string){if(busy)return;setBusy(true);try{const res=await fetch('/api/commercial',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,lead:lead.id,client,confirm:true})});const result:any=await res.json();if(!res.ok)throw Error(result.error);await refresh();setLeadAction(null);if(action==='convert'){openProject(result.project.id);tell(result.existing?'O projeto já existe. Abrindo o registro.':'Cliente, projeto, documentos e cobranças preparados.');}else{setLeadPhase('Projeto');tell('Fechamento confirmado. Agora crie o projeto.');}}finally{setBusy(false)}}
 function projectForm(item?:Item,lead?:Item,clientId?:string){if(!item&&!by('client').length){newClient();return;}setModal({title:item?'Editar projeto':'Novo projeto',kind:'project',item,wizard:!item,extra:lead?{lead:lead.id}:undefined,fields:[{key:'name',label:'Nome do projeto',required:true,value:lead?'Projeto · '+(lead.data.company||lead.data.name):''},{key:'client',label:'Cliente',type:'select',required:true,options:by('client').map(r=>({value:r.id,label:r.data.company||r.data.name})),value:clientId||''},{key:'type',label:'Tipo de contratação',required:true,type:'select',options:opts(services),value:lead?.data.service||''},{key:'integration',label:'Nível de integração',required:true,type:'select',options:integrationLevels.map(value=>({value,label:integrationLabel(value)})),value:integrationFor(item?.data.type||lead?.data.service)},{key:'clientContact',label:'Responsável do cliente',value:lead?.data.name||find(clientId||'')?.data.name||''},{key:'objective',label:'Objetivo',type:'textarea',required:true},{key:'scope',label:'Escopo contratado',type:'textarea',required:true},...macroScopes('type'),{key:'startDate',label:'Data de início',type:'date'},{key:'value',label:'Valor contratado (R$)',type:'money',value:lead?.data.value||0},{key:'due',label:'Conclusão prevista',type:'date'},{key:'status',label:'Situação',required:true,type:'select',options:opts(['Preparação','Ativo','Pausado',...(item?.data.status==='Concluído'?['Concluído']:[]),'Cancelado']),value:'Preparação'},{key:'notes',label:'Notas internas / alterações de escopo',type:'textarea'}]});}
 function addForm(kind:Kind,item?:Item,projectOverride?:string|null){const formProject=projectOverride!==undefined?projectOverride:item?.project??project;let fields:Field[]=[];const titles:Partial<Record<Kind,string>>={task:'tarefa',action:'ação do cliente',stage:'etapa',delivery:'versão de entregável',document:'documento por link',meeting:'reunião',charge:'cobrança',expense:'despesa',update:'atualização',member:'acesso ao projeto'};
 const title:Field={key:'title',label:'Título',required:true};const due:Field={key:'due',label:'Prazo',type:'date'};
 if(kind==='task')fields=[title,{key:'status',label:'Situação',required:true,type:'select',options:opts(['Pendente','Em andamento','Concluída']),value:'Pendente'},due,{key:'owner',label:'Responsável',value:'Gabriel'},{key:'stage',label:'Etapa',type:'select',options:by('stage',formProject).sort((a,b)=>a.data.order-b.data.order).map(r=>({value:r.id,label:r.data.title}))}];
 if(kind==='action')fields=[title,{key:'description',label:'Instruções',type:'textarea'},{key:'status',label:'Situação',required:true,type:'select',options:opts(['Pendente','Enviada','Concluída']),value:'Pendente'},due];
 if(kind==='stage')fields=[title,{key:'status',label:'Situação',required:true,type:'select',options:opts(['Planejada','Atual','Concluída']),value:'Planejada'},{key:'order',label:'Ordem',type:'number',value:by('stage',formProject).length+1},due];
 if(kind==='delivery')fields=[title,{key:'version',label:'Número da versão',type:'number',value:item?.data.version||1,required:true},{key:'description',label:'Conteúdo e orientações para revisão',type:'textarea',required:true},{key:'url',label:'Link da entrega',type:'url'},due,vis];
 if(kind==='document')fields=[title,{key:'url',label:'Link do documento',type:'url',required:true},vis];
 if(kind==='meeting')fields=[title,{key:'date',label:'Data e horário (seu horário local)',type:'datetime-local',required:true},{key:'url',label:'Link da reunião',type:'url'},{key:'agenda',label:'Pauta',type:'textarea'},{key:'summary',label:'Resumo compartilhado e decisões',type:'textarea'},{key:'notes',label:'Notas internas',type:'textarea'},vis];
 if(kind==='charge')fields=[title,{key:'milestone',label:'Marco financeiro (etapa do projeto)',type:'select',options:by('stage',formProject).sort((a,b)=>a.data.order-b.data.order).map(r=>({value:r.id,label:r.data.title}))},{key:'amount',label:'Valor (R$)',type:'money',required:true},due,{key:'url',label:'Link de pagamento',type:'url'},{key:'pix',label:'Chave Pix / instruções',type:'textarea'}];
 if(kind==='expense')fields=[title,{key:'amount',label:'Valor (R$)',type:'money',required:true},{key:'date',label:'Data',type:'date',value:today(),required:true}];
 if(kind==='update')fields=[title,{key:'text',label:'Atualização para o cliente',type:'textarea',required:true},{...vis,value:'published'}];
 if(kind==='member')fields=[{key:'name',label:'Nome do contato',required:true},{key:'email',label:'E-mail da conta de acesso',type:'email',required:true},{key:'approver',label:'Pode aprovar entregáveis',type:'checkbox',value:true},{key:'emailNotifications',label:'Receber avisos por e-mail',type:'checkbox',value:true}];
 setModal({title:(item?'Editar ':'Adicionar ')+(titles[kind]||kind),kind,project:formProject,item,fields,wizard:kind==='delivery'});
 }
 async function exportBackup(){if(busy)return;setBusy(true);setBackupProgress('Exportando dados…');try{const res=await fetch('/api/backup',{cache:'no-store'}),backup:any=await res.json();if(!res.ok)throw Error(backup.error);const zip=new BackupZip();zip.add('dados.json',new TextEncoder().encode(JSON.stringify(backup,null,2)));let total=0;for(let i=0;i<backup.files.length;i++){const file=backup.files[i];setBackupProgress(`Baixando arquivos: ${i+1}/${backup.files.length}`);const response=await fetch('/api/files?id='+encodeURIComponent(file.id),{cache:'no-store'});if(!response.ok)throw Error('Arquivo indisponível: '+file.filename+'. O backup não foi concluído.');const bytes=new Uint8Array(await response.arrayBuffer());total+=bytes.length;if(total>256*1024*1024)throw Error('Os anexos excedem 256 MB. Será necessário exportar em partes.');zip.add(file.path,bytes);}const blob=zip.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='gabriel-business-os-dados-'+today()+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);tell('Backup preparado com dados e todos os anexos referenciados.');}catch(e:any){tell(e.message);}finally{setBusy(false);setBackupProgress('');}}
 function continuation(){const client=find(p?.data.client);setModal({title:'Oportunidade de continuidade',kind:'lead',extra:{source:'Continuidade do projeto '+p?.data.name,service:'Communication Optimization',notes:p?.data.nextSteps||''},fields:leadFields.map(f=>({...f,value:({name:client?.data.name||'',company:client?.data.company||'',email:client?.data.email||'',next:'Conversar sobre os próximos passos'} as any)[f.key]??f.value}))});}
 function receiptForm(c:Item){const paid=chargeTotals(items,c).paid;setModal({title:'Confirmar recebimento',kind:'receipt',project:c.project,extra:{charge:c.id},fields:[{key:'amount',label:'Valor recebido (R$)',type:'money',required:true,value:c.data.amount-paid},{key:'date',label:'Data do recebimento',type:'date',value:today(),required:true},{key:'note',label:'Referência / observação'}]});}
 async function seed(){await run(async()=>{const c=(await create('client',{name:'Marina Costa',company:'Aurora Studio · exemplo',email:'marina@example.com',notes:'Cliente fictício para testar a V1.'})).item;const pr=(await create('project',{name:'Comunicação que conduz à ação',client:c.id,type:'Communication Implementation',objective:'Organizar a mensagem comercial e orientar a captação de oportunidades.',scope:'Direção de mensagem, copy de landing page e orientações de implementação.',value:600000,status:'Ativo',due:'2026-10-30'})).item;await create('delivery',{title:'Landing page',version:1,description:'Seu espaço também comunica quem você é.\n\nProjetos de interiores que traduzem sua rotina, suas escolhas e a maneira como você quer viver.\n\nRevise a proposta de valor e a chamada para ação. Conteúdo fictício de teste.',visibility:'published',due:'2026-10-15'},pr.id);await create('task',{title:'Preparar orientações de implementação',status:'Pendente',owner:'Gabriel',due:'2026-10-19'},pr.id);await create('charge',{title:'Entrada · 50%',amount:300000,due:'2026-10-10',pix:'Configure sua chave Pix antes de cobrar.'},pr.id);await create('charge',{title:'Entrega final · 50%',amount:300000,due:'2026-10-30'},pr.id);await create('update',{title:'Primeira versão disponível',text:'A direção estratégica foi traduzida na primeira versão da página. O próximo passo é revisar a mensagem.',visibility:'published'},pr.id);await create('meeting',{title:'Revisão e alinhamento',date:'2026-10-16T14:00',agenda:'Revisar a mensagem e consolidar os próximos passos.',visibility:'published'},pr.id);await create('lead',{name:'João Ribeiro · exemplo',company:'Ribeiro Consultoria',email:'joao@example.com',stage:'Novo lead',source:'Site',next:'Agendar Discovery',value:450000});setSeedConfirm(false);},'Projeto de exemplo criado. Você pode editar ou concluir os registros.');}
 async function upload(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;await run(async()=>{const data=new FormData(form);data.set('project',project!);const r=await fetch('/api/files',{method:'POST',body:data});const j:any=await r.json();if(!r.ok)throw Error(j.error);form.reset();},'Arquivo enviado e salvo.');}
 function rowActions(r:Item,edit:()=>void){return !isClient&&<div className="row-actions"><button aria-label={'Editar '+(r.data.title||r.data.name)} className="icon-button" onClick={edit}><Edit3 size={15}/></button>{!['receipt','approval','activity','comment'].includes(r.kind)&&<button className="icon-button" aria-label="Remover registro" onClick={()=>setDeleteTarget(r)}><Trash2 size={15}/></button>}</div>}
 const LinkButton=({url,label='Abrir link'}:{url?:string;label?:string})=>safeLink(url||'')?<a className="text-link" href={safeLink(url!)} target="_blank" rel="noopener noreferrer">{label}<ArrowUpRight size={14}/></a>:null;
 function empty(text:string){return <div className="empty"><Folder size={24}/><p>{text}</p></div>}
 function finances(pid?:string){return <FinancePanel key={(pid||'global')+view} items={items} project={pid} client={isClient} busy={busy} add={kind=>{if(kind==='expense')addForm(kind,undefined,pid||null);else if(pid)addForm(kind,undefined,pid);else setModal({title:'Escolher projeto para a cobrança',kind:'charge',fields:[{key:'chooseProject',label:'Projeto',type:'select',required:true,options:projects.map(r=>({value:r.id,label:r.data.name}))}]});}} edit={r=>addForm(r.kind,r,r.project)} remove={setDeleteTarget} receive={receiptForm} operation={(action,item)=>setFinanceTarget({action,item,operationId:crypto.randomUUID()})} openProject={openProject}/>}
 function projectList(compact=false){const list=projects.filter(r=>(projectFilter==='Arquivados'&&!compact?!!r.data.archived:!r.data.archived)&&(compact||((r.data.name+' '+r.data.type).toLowerCase().includes(query.toLowerCase())&&(['Todos','Arquivados'].includes(projectFilter)||(projectFilter==='Em andamento'?!['Concluído','Cancelado'].includes(r.data.status):r.data.status==='Concluído')))));return <>{!compact&&<><div className="toolbar between"><div className="filter-chips">{['Todos','Em andamento','Concluídos','Arquivados'].map(f=><button aria-pressed={projectFilter===f} className={projectFilter===f?'selected':''} key={f} onClick={()=>setProjectFilter(f)}>{f}</button>)}</div>{!isClient&&<button className="primary" onClick={()=>projectForm()}><Plus size={16}/> Novo projeto</button>}</div><SearchField value={query} onChange={setQuery} label="Buscar projetos"/></>}{!list.length?empty('Nenhum projeto encontrado.'): <div className="project-grid">{list.map(r=>{const stages=by('stage',r.id),done=stages.filter(x=>x.data.status==='Concluída').length,current=stages.find(x=>x.data.status==='Atual');return <button className="project-card" key={r.id} onClick={()=>openProject(r.id)}><div className="row"><span className="status">{r.data.archived?'Arquivado · '+r.data.status:r.data.status}</span><ChevronRight size={18}/></div><h2>{r.data.name}</h2><p className="muted">{current?.data.title||r.data.type}</p><div className="progress-track" role="progressbar" aria-label="Etapas concluídas" aria-valuemin={0} aria-valuemax={stages.length||1} aria-valuenow={done}><span style={{width:(stages.length?done/stages.length*100:0)+'%'}}/></div><div className="row small muted"><span>{done}/{stages.length} etapas</span><span>{date(r.data.due)}</span></div></button>})}</div>}</>}
 function preparation(){const steps=[{title:'Escopo e datas',done:!!(p?.data.scope&&p?.data.due),action:()=>projectForm(p),button:'Ajustar projeto'},{title:'Condições de pagamento',done:by('charge',project).length>0,action:()=>setTab('Financeiro'),button:'Definir cobranças'},{title:'Acesso do cliente',done:by('member',project).length>0,action:()=>setTab('Acesso'),button:'Autorizar contato'},{title:'Materiais de onboarding',done:by('action',project).some(r=>r.data.status==='Concluída'&&(r.data.purpose==='onboarding'||r.data.title==='Enviar materiais para o onboarding')),action:()=>setTab('Plano e tarefas'),button:'Ver solicitações'},{title:'Kick-off',done:by('meeting',project).length>0,action:()=>setTab('Reuniões'),button:'Agendar reunião'}];return <section className="section setup-panel"><div className="row"><h2>Preparar projeto</h2><span className="status">{steps.filter(x=>x.done).length}/{steps.length} itens</span></div><p className="muted">Confira o combinado antes de iniciar. A sequência pode variar conforme o contrato.</p>{steps.map(x=><button key={x.title} className="setup-step" onClick={x.action}><span className={'setup-check '+(x.done?'done':'')}>{x.done?<Check size={14}/>:null}</span><span className="grow">{x.title}</span><span className="muted">{x.done?'Consultar':x.button}</span><ChevronRight size={14}/></button>)}<div className="toolbar"><button className="primary" disabled={busy} onClick={()=>run(()=>patch(p!,{status:'Ativo',startDate:p?.data.startDate||today()}),'Projeto iniciado.')}>Iniciar execução <ArrowUpRight size={14}/></button></div></section>}
 function overview(){const actions=by('action',project).filter(r=>r.data.status==='Pendente'),pending=by('delivery',project).filter(r=>r.data.visibility==='published'&&!by('approval',project).some(a=>a.data.delivery===r.id)),stages=by('stage',project).sort((a,b)=>a.data.order-b.data.order),current=stages.find(r=>r.data.status==='Atual'),updates=by('update',project).filter(r=>isClient?r.data.visibility==='published':true),meetings=by('meeting',project).filter(r=>r.data.date>=localDateTime()).sort((a,b)=>a.data.date.localeCompare(b.data.date));return <>{!isClient&&p?.data.status==='Preparação'&&preparation()}{p?.data.status==='Concluído'&&<div className="attention"><h3>Projeto concluído</h3><p>Consulte os materiais finais e as orientações para continuar.</p><button onClick={()=>setTab('Entrega final')}>Abrir entrega final <ArrowUpRight size={14}/></button></div>}<div className="project-snapshot"><div><span>{p?.data.status==='Concluído'?'SITUAÇÃO DO PROJETO':'ETAPA ATUAL'}</span><h2>{p?.data.status==='Concluído'?'Projeto concluído':current?.data.title||'Preparação'}</h2><p>{stages.filter(r=>r.data.status==='Concluída').length} de {stages.length} etapas concluídas</p></div><div className="snapshot-actions"><button onClick={()=>setTab(isClient?'Etapas':'Plano e tarefas')}>Abrir plano <ChevronRight size={15}/></button>{!isClient&&<><button onClick={()=>addForm('update')}><Plus size={15}/> Atualizar cliente</button><button onClick={()=>setTab('Entrega final')}>{p?.data.status==='Concluído'?'Ver encerramento':'Preparar encerramento'} <ChevronRight size={15}/></button></>}</div></div>{isClient&&(pending.length||actions.length)>0&&<div className="attention"><div className="eyebrow">Sua próxima ação</div><h2>{pending.length?'Revise '+pending[0].data.title+'.':actions[0].data.title}</h2><p>{pending.length?'Sua revisão orienta a próxima rodada de trabalho.':actions[0].data.description}</p><button className="primary" onClick={()=>{if(pending.length){setTab('Entregáveis');setDelivery(pending[0].id)}else setActionTarget(actions[0])}}>{pending.length?'Revisar entrega':'Ver solicitação'}<ArrowUpRight size={15}/></button></div>}<div className="two-cols"><div><Section number="01" title={isClient?'Onde estamos':'Resumo operacional'}><h3>{current?.data.title||'Etapa atual a definir'}</h3><p>{p?.data.objective}</p>{!isClient&&<div className="row"><span className="status">{pending.length} revisão(ões) aguardando cliente</span><span className="status">{by('task',project).filter(r=>r.data.status!=='Concluída').length} tarefa(s) aberta(s)</span></div>}</Section><Section number="02" title="Atualizações do projeto">{!isClient&&<button className="small-button" onClick={()=>addForm('update')}><Plus size={14}/> Publicar atualização</button>}{updates.length?updates.slice(0,4).map(r=><div className="update" key={r.id}><div className="row"><h3>{r.data.title}</h3>{rowActions(r,()=>addForm('update',r))}</div><p className="pre">{r.data.text}</p><span className="muted">{date(r.created)} · {r.data.visibility==='published'?'Publicado':'Interno'}</span></div>):empty('Nenhuma atualização publicada.')}</Section><details className="scope-details"><summary>Objetivo e escopo contratado</summary><p className="pre">{p?.data.scope}</p>{p?.data.type==='Communication Project'&&<><h3>Strategic Phase</h3><p className="pre">{p.data.strategicScope||'Consulte o SOW contratado.'}</p><h3>Implementation Phase</h3><p className="pre">{p.data.implementationScope||'Consulte o SOW contratado.'}</p></>}<h3>Integração e responsabilidades</h3><p>{integrationLabel(p?.data.integration||integrationFor(p?.data.type))}</p><p className="muted">{integrationDescriptions[p?.data.integration||integrationFor(p?.data.type)]}</p>{p?.data.clientContact&&<p>Responsável do cliente: {p.data.clientContact}</p>}{p?.data.startDate&&<p>Início: {date(p.data.startDate)}</p>}{!isClient&&p?.data.notes&&<div className="internal"><div className="eyebrow">Notas internas</div><p className="pre">{p.data.notes}</p></div>}</details></div><div><Section title="Etapas do projeto"><ol className="stages">{stages.map(r=><li key={r.id}><span>{r.data.status==='Concluída'?<Check size={16}/>:String(r.data.order).padStart(2,'0')}</span><div><h3>{r.data.title}</h3><p className="muted">{r.data.status}{r.data.due?' · '+date(r.data.due):''}</p></div></li>)}</ol><button className="text-link" onClick={()=>setTab(isClient?'Etapas':'Plano e tarefas')}>Ver plano completo <ArrowUpRight size={14}/></button></Section><Section title="Próxima reunião">{meetings.length?<><h3>{meetings[0].data.title}</h3><p>{date(meetings[0].data.date)} · {meetings[0].data.date.slice(11,16)}</p><LinkButton url={meetings[0].data.url} label="Entrar na reunião"/></>:<p className="muted">Nenhuma reunião futura registrada.</p>}</Section>{!isClient&&<Section title="Atividade recente">{by('activity',project).slice(0,5).map(r=><div className="activity" key={r.id}>{r.data.text}<p className="muted">{r.data.actor} · {date(r.created)}</p></div>)}</Section>}</div></div></>}
 function plan(){const stages=by('stage',project).sort((a,b)=>a.data.order-b.data.order);return <>{!isClient&&<div className="toolbar"><button onClick={()=>addForm('stage')}><Plus size={15}/> Etapa</button><button onClick={()=>addForm('task')}><Plus size={15}/> Tarefa interna</button><button className="primary" onClick={()=>addForm('action')}><Plus size={15}/> Ação do cliente</button></div>}<Section title="Etapas e marcos">{stages.map(r=><div className="list-row" key={r.id}><div><h3>{String(r.data.order).padStart(2,'0')} / {r.data.title}</h3><p className="muted">{date(r.data.due)}</p></div>{!isClient?<select className="inline-select" aria-label={"Situação de "+r.data.title} value={r.data.status} disabled={busy} onChange={e=>run(()=>patch(r,{status:e.target.value}),"Etapa atualizada.")}>{["Planejada","Atual","Concluída"].map(v=><option key={v}>{v}</option>)}</select>:<span className="status">{r.data.status}</span>}{rowActions(r,()=>addForm('stage',r))}</div>)}</Section>{!isClient&&<Section title="Tarefas internas">{taskRows(by('task',project))}</Section>}<Section title="Ações do cliente">{taskRows(by('action',project))}</Section></>}
 function taskRows(rows:Item[]){return rows.length?rows.map(r=><div className="list-row" key={r.id}>{r.kind==='task'&&<button className={'check-button '+(r.data.status==='Concluída'?'done':'')} disabled={busy} aria-label={r.data.status==='Concluída'?'Reabrir tarefa':'Concluir tarefa'} onClick={()=>run(()=>patch(r,{status:r.data.status==='Concluída'?'Pendente':'Concluída'}),'Situação atualizada.')}><Check size={16}/></button>}<div className="grow"><h3>{r.data.title}</h3><p className="muted">{r.kind==='action'&&r.data.status==='Enviada'?'Aguardando conferência':r.data.status} · {date(r.data.due)}{r.data.owner?' · '+r.data.owner:''}</p>{r.data.description&&<p>{r.data.description}</p>}{!project&&<button className="text-link" onClick={()=>openProject(r.project!)}>{find(r.project!)?.data.name}<ArrowUpRight size={12}/></button>}</div>{r.kind==='action'?<><button className="small-button" onClick={()=>{if(!project)openProject(r.project!);setActionTarget(r)}}>{isClient?(r.data.status==='Pendente'?'Responder':'Ver resposta'):(r.data.status==='Enviada'?'Conferir envio':'Ver solicitação')}<ChevronRight size={14}/></button>{rowActions(r,()=>setModal({title:'Editar solicitação',kind:'action',project:r.project,item:r,fields:[{key:'title',label:'Título',required:true},{key:'description',label:'Instruções',type:'textarea'},{key:'due',label:'Prazo',type:'date'}]}))}</>:rowActions(r,()=>setModal({title:'Editar tarefa',kind:r.kind,item:r,project:r.project,fields:[{key:'title',label:'Título',required:true},{key:'status',label:'Situação',required:true,type:'select',options:opts(['Pendente','Em andamento','Concluída'])},{key:'due',label:'Prazo',type:'date'},{key:'description',label:'Instruções',type:'textarea'}]}))}</div>):empty('Nenhuma tarefa registrada.')}
 function deliveries(){const d=find(delivery||'');if(d){const decision=by('approval',project).find(r=>r.data.delivery===d.id);return <><button className="text-link" onClick={()=>setDelivery(null)}><ArrowLeft size={15}/> Todos os entregáveis</button><div className="delivery-page"><div className="eyebrow">Versão {d.data.version} / {d.data.visibility==='published'?'Publicada':'Rascunho interno'}</div><h2>{d.data.title}</h2><p className="muted">Prazo da revisão: {date(d.data.due)}</p><div className="delivery-body pre">{d.data.description}</div><LinkButton url={d.data.url} label="Abrir material completo"/>{decision?<div className="attention"><h3>{decision.data.decision==='approved'?'Versão aprovada':'Ajustes solicitados'}</h3><p className="pre">{decision.data.text}</p><p className="muted">{decision.data.author} · {date(decision.created)} · versão {d.data.version}</p></div>:d.data.visibility==='published'&&<div className="review-box"><p className="muted">Comentários mantêm a revisão aberta. Solicitar ajustes ou aprovar registra uma decisão sobre esta versão.</p><label htmlFor="feedback">Comentários ou ajustes para esta versão</label><textarea id="feedback" value={feedback} onChange={e=>setFeedback(e.target.value)} placeholder="Descreva seu retorno..."/><div className="toolbar"><button disabled={busy} onClick={()=>{if(!feedback.trim()){tell('Escreva seu comentário.');return;}run(async()=>{await create('comment',{delivery:d.id,text:feedback},project);setFeedback('')},'Comentário enviado.')}}>Enviar comentário</button><button disabled={busy||(!user.admin&&!user.approverProjects?.includes(project))} onClick={()=>{if(!feedback.trim()){tell('Descreva os ajustes solicitados.');return;}run(()=>create('approval',{delivery:d.id,decision:'changes',text:feedback},project),'Solicitação de ajustes registrada.')}}>Solicitar ajustes</button><button className="primary" disabled={busy||(!user.admin&&!user.approverProjects?.includes(project))} onClick={()=>setModal({title:'Aprovar '+d.data.title+' · v'+d.data.version+'?',kind:'approval',project,extra:{delivery:d.id,decision:'approved'},fields:[{key:'text',label:'Observação (opcional)',type:'textarea'}]})}>Aprovar versão {d.data.version}<Check size={15}/></button></div></div>}<Section title="Comentários da versão">{by('comment',project).filter(r=>r.data.delivery===d.id).map(r=><div className="update" key={r.id}><p className="pre">{r.data.text}</p><span className="muted">{r.data.author} · {date(r.created)}</span></div>)}</Section>{!isClient&&<button onClick={()=>{setModal({title:'Publicar nova versão',kind:'delivery',project,wizard:true,fields:[{key:'title',label:'Título',required:true,value:d.data.title},{key:'version',label:'Número da versão',type:'number',value:Number(d.data.version)+1},{key:'description',label:'Conteúdo / instruções',type:'textarea',required:true,value:d.data.description},{key:'url',label:'Link',type:'url',value:d.data.url},{key:'due',label:'Prazo',type:'date'},vis]})}}><Plus size={15}/> Criar próxima versão</button>}</div></>}
 const rows=by('delivery',project);return <>{!isClient&&<div className="toolbar"><button className="primary" onClick={()=>addForm('delivery')}><Plus size={15}/> Novo entregável / versão</button></div>}{rows.length?rows.map(r=>{const a=by('approval',project).find(a=>a.data.delivery===r.id);return <div className="list-row" key={r.id}><button className="plain grow" onClick={()=>{setDelivery(r.id);setFeedback('')}}><h3>{r.data.title}<span className="version">v{r.data.version}</span></h3><p className="muted">{r.data.visibility==='internal'?'Rascunho interno':a?a.data.decision==='approved'?'Aprovado':'Ajustes solicitados':'Aguardando revisão'} · {date(r.data.due)}</p></button><ChevronRight size={16}/>{!a&&rowActions(r,()=>addForm('delivery',r))}</div>;}):empty('Os entregáveis aparecerão aqui quando forem publicados.')}</>}
 function documents(){return <>{uploadAction&&find(uploadAction)&&<div className="attention"><h3>{find(uploadAction)?.data.title}</h3><p className="muted">Os arquivos enviados serão vinculados à solicitação. Depois, envie a resposta para conferência.</p><button className="text-link" onClick={()=>setActionTarget(find(uploadAction)!)}>Voltar à solicitação <ArrowUpRight size={14}/></button></div>}<div className="upload-box"><h3>Enviar um arquivo</h3><form onSubmit={upload}><label>Título<input name="title" placeholder="Ex.: materiais da marca / comprovante"/></label><label>Arquivo · até 20 MB<input name="file" type="file" required/></label><label>Vincular a uma solicitação<select name="action" value={uploadAction} onChange={e=>setUploadAction(e.target.value)}><option value="">Documento geral do projeto</option>{by('action',project).filter(r=>r.data.status!=='Concluída').map(r=><option key={r.id} value={r.id}>{r.data.title}</option>)}</select></label>{!isClient&&<label>Visibilidade<select name="visibility"><option value="published">Compartilhado com o cliente</option><option value="internal">Interno</option></select></label>}<button className="primary" disabled={busy}><Upload size={15}/> Enviar arquivo</button></form></div>{!isClient&&<div className="toolbar"><button onClick={()=>addForm('document')}><Plus size={15}/> Adicionar documento por link</button></div>}{by('document',project).length?by('document',project).map(r=><div className="list-row" key={r.id}><FileText size={18}/><div className="grow"><h3>{r.data.title}</h3><p className="muted">{date(r.created)}{!isClient?' · '+(r.data.visibility==='internal'?'Interno':'Compartilhado'):''}</p></div>{r.data.file?<a href={'/api/files?id='+r.id} className="text-link">Baixar <ArrowUpRight size={14}/></a>:<LinkButton url={r.data.url}/>} {!r.data.file&&rowActions(r,()=>addForm('document',r))}</div>):empty('Nenhum documento disponível.')}</>}
 function meetings(){return <>{!isClient&&<div className="toolbar"><button className="primary" onClick={()=>addForm('meeting')}><Plus size={15}/> Nova reunião</button></div>}{by('meeting',project).length?by('meeting',project).sort((a,b)=>b.data.date.localeCompare(a.data.date)).map(r=><section className="meeting" key={r.id}><div className="row"><div className="eyebrow">{date(r.data.date)} · {r.data.date.slice(11,16)} · horário local</div>{rowActions(r,()=>addForm('meeting',r))}</div><h2>{r.data.title}</h2><LinkButton url={r.data.url} label="Entrar na reunião"/>{r.data.agenda&&<><h3>Pauta</h3><p className="pre">{r.data.agenda}</p></>}{r.data.summary&&<><h3>Decisões e próximos passos</h3><p className="pre">{r.data.summary}</p></>}{!isClient&&<><span className="status">{r.data.visibility==='internal'?'Interna':'Compartilhada'}</span>{r.data.notes&&<div className="internal"><h3>Notas internas</h3><p>{r.data.notes}</p></div>}</>}</section>):empty('Nenhuma reunião registrada.')}</>}
 async function copyAccess(r:Item){try{await navigator.clipboard.writeText(`Olá, ${r.data.name}! Seu espaço do projeto ${p?.data.name} está disponível em ${window.location.origin}/. Entre no Portal usando o e-mail ${r.data.email}. Você pode acompanhar o projeto, enviar materiais e comentar entregáveis.${r.data.approver?' Você também pode aprovar versões ou solicitar ajustes.':''}`);tell('Instruções copiadas. Envie ao cliente para acessar o Portal.');}catch{tell('Não foi possível copiar. Use o endereço do Portal e o e-mail autorizado abaixo.');}}
 function access(){return <><div className="attention"><h3>Preparar o acesso do cliente</h3><ol className="access-steps"><li>Autorize o mesmo e-mail que o cliente usará no login.</li><li>O cliente pode entrar com Google ou criar um acesso com e-mail e senha.</li><li>Copie as instruções abaixo e envie ao contato.</li><li>Peça que entre com a própria conta. O primeiro acesso aparecerá aqui após atualizar.</li></ol><p className="small">O acesso é limitado aos projetos autorizados para este e-mail. Copie as instruções abaixo para orientar o cliente.</p></div><div className="toolbar"><button className="primary" onClick={()=>addForm('member')}><Plus size={15}/> Autorizar contato</button><button disabled={busy} onClick={()=>run(()=>Promise.resolve(),'Acessos atualizados.')}>Atualizar acessos</button></div>{by('member',project).length?by('member',project).map(r=><div className="list-row access-row" key={r.id}><div className="grow"><h3>{r.data.name}</h3><p className="muted">{r.data.email} · {r.data.approver?'Pode aprovar e solicitar ajustes':'Pode consultar, comentar e enviar materiais'}</p><span className="status">{r.data.firstAccessAt?'Primeiro acesso confirmado · '+new Date(r.data.firstAccessAt).toLocaleString('pt-BR',{hour12:false}):'Aguardando primeiro acesso'}</span></div><button onClick={()=>copyAccess(r)}>Copiar instruções</button>{rowActions(r,()=>addForm('member',r))}</div>):empty('Autorize um contato para começar o teste de acesso.')}</>}

 function commercial(){const leads=by('lead').map<Item>(r=>({...r,data:{...r.data,stage:pipelineStage(r.data.stage)}})).filter(r=>(r.data.name+' '+r.data.company).toLowerCase().includes(query.toLowerCase()));return <><div className="toolbar"><button className="primary" onClick={()=>setModal({title:'Nova oportunidade',kind:'lead',fields:leadFields})}><Plus size={15}/> Nova oportunidade</button></div><SearchField value={query} onChange={setQuery} label="Buscar oportunidades"/><div className="pipeline">{[...pipeline,...new Set(leads.map(r=>r.data.stage).filter(stage=>!pipeline.includes(stage)))].map(stage=><section key={stage}><div className="pipeline-heading">{pipelineLabel(stage)}<span>{leads.filter(r=>r.data.stage===stage).length}</span></div>{leads.filter(r=>r.data.stage===stage).map(r=><div className="lead-card" key={r.id}><h3>{r.data.company||r.data.name}</h3><p className="muted">{r.data.name} · {money(r.data.value)}</p><p>{r.data.next||'Defina a próxima ação'}</p><p className="muted">{date(r.data.due)}</p>{r.data.recommendedPath&&<p className="small">Caminho: {r.data.recommendedPath}</p>}{stage!=='Ganho'&&<select className="inline-select" aria-label={'Etapa comercial de '+r.data.name} value={r.data.stage} disabled={busy} onChange={e=>run(()=>patch(r,{stage:e.target.value}),'Oportunidade atualizada.')}>{pipeline.filter(x=>x!=='Ganho').map(v=><option key={v} value={v}>{pipelineLabel(v)}</option>)}</select>}<div className="toolbar"><button className="small-button" onClick={()=>openLead(r)}>Abrir oportunidade <ChevronRight size={14}/></button>{rowActions(r,()=>openLead(r))}</div>{stage==='Ganho'&&<button className="text-link" onClick={()=>{const existing=projects.find(p=>p.data.lead===r.id);if(existing)openProject(existing.id);else{openLead(r);setLeadAction('convert')}}}>{projects.some(p=>p.data.lead===r.id)?'Abrir projeto':'Criar projeto'} <ArrowUpRight size={13}/></button>}</div>)}</section>)}</div></>}
 function openAppointment(r:{project?:string;lead?:string}){if(r.project){openProject(r.project);setTab('Reuniões')}else if(r.lead&&find(r.lead)){openLead(find(r.lead)!);setLeadPhase('Discovery')}}
 function agenda(){const now=localDateTime(),entries=agendaEntries(items),filtered=entries.filter(r=>(agendaPeriod==='Todos'||(agendaPeriod==='Próximos'?r.date>=now&&!r.done:r.date<now||r.done))&&(agendaType==='Todos'||r.type===agendaType)&&(!agendaProject||r.project===agendaProject)&&(r.title+' '+(find(r.project||'')?.data.name||'')).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));return <><div className="toolbar between"><div className="filter-chips">{['Próximos','Todos','Anteriores'].map(v=><button key={v} aria-pressed={agendaPeriod===v} className={agendaPeriod===v?'selected':''} onClick={()=>setAgendaPeriod(v)}>{v}</button>)}</div><span className="muted">{filtered.length} compromisso(s) · horários locais, 24 horas</span></div><div className="agenda-filters"><SearchField value={query} onChange={setQuery} label="Buscar compromisso"/><label>Tipo<select value={agendaType} onChange={e=>setAgendaType(e.target.value)}><option>Todos</option><option>Reunião</option>{!isClient&&<option>Discovery</option>}</select></label><label>Projeto<select value={agendaProject} onChange={e=>setAgendaProject(e.target.value)}><option value="">Todos os projetos</option>{projects.map(r=><option value={r.id} key={r.id}>{r.data.name}</option>)}</select></label></div><Section title="Compromissos">{filtered.length?appointmentMonths(filtered).map(group=><section className="agenda-month" key={group.month} aria-label={group.label}><h3 className="agenda-month-heading">{group.label}</h3>{group.appointments.map(r=><button className="agenda-card agenda-full-row" key={r.id} onClick={()=>openAppointment(r)}><div className="calendar-tile"><strong>{Number(r.date.slice(8,10))}</strong><span>{new Date(r.date).toLocaleDateString('pt-BR',{month:'short'})}</span></div><div className="grow"><h3>{r.title}</h3><p className="muted">{date(r.date)} · {r.date.slice(11,16)}{r.project?' · '+find(r.project)?.data.name:''}</p></div><span className="status">{r.type}{r.done?' · Realizada':r.date<now?' · Anterior':''}</span><ChevronRight size={15}/></button>)}</section>):empty('Nenhum compromisso neste filtro.')}</Section></>}
 function dashboard(){const tasks=by('task').filter(r=>!find(r.project!)?.data.archived&&r.data.status!=='Concluída'),actions=by('action').filter(r=>!find(r.project!)?.data.archived&&r.data.status!=='Concluída'&&(!isClient||r.data.status==='Pendente')),pending=by('delivery').filter(r=>!find(r.project!)?.data.archived&&r.data.visibility==='published'&&!by('approval').some(a=>a.data.delivery===r.id)),next=by('lead').filter(r=>r.data.next&&!['Ganho','Perdido'].includes(r.data.stage));const queue=[...pending.map(r=>({r,label:'Revisão',title:'Revisar '+r.data.title,detail:find(r.project!)?.data.name,open:()=>{openProject(r.project!);setTab('Entregáveis');setDelivery(r.id)}})),...actions.map(r=>({r,label:'Cliente',title:r.data.status==='Enviada'?'Conferir: '+r.data.title:r.data.title,detail:find(r.project!)?.data.name,open:()=>{openProject(r.project!);setActionTarget(r)}})),...(!isClient?next.map(r=>({r,label:'Comercial',title:r.data.next,detail:r.data.company||r.data.name,open:()=>openLead(r)})):[])].sort((a,b)=>(a.r.data.due||'9999').localeCompare(b.r.data.due||'9999'));const filtered=queue.filter(x=>!find(x.r.project||'')?.data.archived&&(focusFilter==='Todas'||x.label===focusFilter));return <><div className="dashboard-heading"><div><div className="workspace-date">{new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</div><h1>{isClient?'Seus projetos':'Operação'}</h1><p className="muted">{isClient?'Acompanhe as entregas e responda às solicitações.':'Acompanhe a operação e resolva as próximas ações.'}</p></div>{!isClient&&<div className="toolbar"><button onClick={()=>setModal({title:'Nova oportunidade',kind:'lead',fields:leadFields})}><Plus size={15}/> Oportunidade</button><button className="primary" onClick={()=>{if(!by('client').length)newClient();else projectForm()}}><Plus size={15}/>{by('client').length?'Novo projeto':'Novo cliente'}</button></div>}</div><div className="metrics interactive-metrics"><button onClick={()=>navigate(isClient?'Pendências':'Comercial')}><span>{isClient?'Suas pendências':'Oportunidades abertas'}<ArrowUpRight size={14}/></span><strong>{isClient?queue.length:by('lead').filter(r=>!['Ganho','Perdido'].includes(r.data.stage)).length}</strong><small>{isClient?'Ver solicitações':'Abrir CRM'}</small></button><button onClick={()=>{setProjectFilter('Em andamento');navigate(isClient?'Meus projetos':'Projetos')}}><span>Projetos em andamento<ArrowUpRight size={14}/></span><strong>{projects.filter(r=>!r.data.archived&&!['Concluído','Cancelado'].includes(r.data.status)).length}</strong><small>Ver projetos</small></button><button onClick={()=>{setFocusFilter('Revisão');document.getElementById('attention-queue')?.scrollIntoView({behavior:'smooth',block:'start'})}}><span>Revisões pendentes<ArrowUpRight size={14}/></span><strong>{pending.length}</strong><small>Ver entregas</small></button>{!isClient&&<button onClick={()=>navigate('Financeiro')}><span>Saldo a receber<ArrowUpRight size={14}/></span><strong>{money(outstanding(items))}</strong><small>Abrir financeiro</small></button>}</div>{!projects.length&&!isClient&&<div className="attention"><h2>Crie seu primeiro projeto</h2><p>Cadastre um cliente ou explore o painel com dados de exemplo.</p><div className="toolbar"><button className="primary" onClick={newClient}>Cadastrar cliente</button><button onClick={()=>setSeedConfirm(true)}>Carregar exemplo</button></div></div>}<div className={isClient?'':'two-cols dashboard-grid'}><section className="section" id="attention-queue"><div className="row section-heading"><h2>{isClient?'Ações que precisam de você':'Precisa de atenção'}</h2><span className="count-badge">{queue.length}</span></div><div className="filter-chips">{['Todas','Revisão','Cliente',...(!isClient?['Comercial']:[])].map(f=><button key={f} aria-pressed={focusFilter===f} className={focusFilter===f?'selected':''} onClick={()=>setFocusFilter(f)}>{f}</button>)}</div>{filtered.length?filtered.map(({r,label,title,detail,open})=><button className="list-row plain actionable-row" key={r.id} onClick={open}><div className="grow"><span className="queue-label">{label}</span><h3>{title}</h3><p className="muted">{detail}</p></div><div className="row"><span className={'status '+(r.data.due&&r.data.due<today()?'warn':'')}>{r.data.due?date(r.data.due):'Sem prazo'}</span><ChevronRight size={16}/></div></button>):empty('Nenhuma pendência neste filtro.')}</section>{!isClient&&<Section title="Sua agenda">{nextAppointments(items,localDateTime()).slice(0,3).map(r=><button className="agenda-card" key={r.id} onClick={()=>openAppointment(r)}><div className="calendar-tile"><strong>{Number(r.date.slice(8,10))}</strong><span>{new Date(r.date).toLocaleDateString('pt-BR',{month:'short'})}</span></div><div className="grow"><h3>{r.title}</h3><p className="muted">{date(r.date)} · {r.date.slice(11,16)}{r.project?' · '+find(r.project)?.data.name:''}</p></div><ChevronRight size={15}/></button>)}{!nextAppointments(items,localDateTime()).length&&<p className="muted">Nenhum compromisso próximo.</p>}<button className="text-link agenda-open" onClick={()=>{setAgendaPeriod('Todos');navigate('Agenda')}}>Abrir agenda completa <ArrowUpRight size={14}/></button><div className="subheading">Tarefas abertas</div><p className="muted">Clique no círculo para concluir uma tarefa.</p>{taskRows(tasks.sort((a,b)=>(a.data.due||'9999').localeCompare(b.data.due||'9999')).slice(0,5))}<button className="text-link" onClick={()=>navigate('Tarefas')}>Ver todas as tarefas <ChevronRight size={14}/></button></Section>}</div><Section title="Projetos em foco">{projectList(true)}</Section></>}
 function pendingPage(){return <><Section title="Revisões pendentes">{by('delivery').filter(r=>r.data.visibility==='published'&&!by('approval').some(a=>a.data.delivery===r.id)).map(r=><button className="list-row plain" key={r.id} onClick={()=>{openProject(r.project!);setTab('Entregáveis');setDelivery(r.id)}}><div><h3>{r.data.title} · versão {r.data.version}</h3><p className="muted">{date(r.data.due)} · {find(r.project!)?.data.name}</p></div><ChevronRight size={18}/></button>)}</Section><Section title="Materiais e outras ações">{taskRows(by('action').filter(r=>r.data.status!=='Concluída'))}</Section></>}
 const navItems=isClient?['Início','Meus projetos','Pendências','Agenda','Minha conta']:['Visão geral','Comercial','Clientes','Projetos','Tarefas','Agenda','Financeiro','Configurações'];
 const navIcons:any={'Agenda':Calendar,'Visão geral':LayoutDashboard,'Início':LayoutDashboard,'Comercial':Briefcase,'Clientes':Users,'Projetos':Folder,'Meus projetos':Folder,'Tarefas':CheckSquare,'Pendências':CheckSquare,'Financeiro':Wallet,'Configurações':Settings,'Minha conta':Users};
 if(error)return <div className="login-state"><div className="brand">Gabriel Gomes.</div><h1>Acesso ao seu espaço.</h1><p>{error}</p>{error.includes('projetos autorizados')&&<p className="muted">Confira se está usando o e-mail autorizado pelo responsável pelo projeto. Se o acesso ainda não foi cadastrado, peça a liberação desse e-mail.</p>}<a className="primary button" href="/logout" target="_top">Trocar conta</a></div>;
